#!/usr/bin/env node
// Regenerates netlify/functions/_lib/migrations.generated.ts from migrations/NNNN_*.sql so the functions bundle
// carries the SQL (Netlify functions cannot rely on reading repo files at run time).
// Usage: node scripts/db/embed-migrations.mjs [--check]
// --check exits 1 when the generated file is out of date (CI; tests/backend/migrations.test.ts checks it too).
import { readdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { execFileSync } from 'node:child_process';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const dir = join(root, 'migrations');
const out = join(root, 'netlify', 'functions', '_lib', 'migrations.generated.ts');

const files = readdirSync(dir)
  .filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f))
  .sort();

const body = [
  '// AUTO-GENERATED by scripts/db/embed-migrations.mjs from migrations/*.sql. Do not edit by hand.',
  '// tests/backend/migrations.test.ts fails when this file and the .sql files disagree.',
  'export const MIGRATION_FILES: ReadonlyArray<{ file: string; sql: string }> = [',
  // eslint-disable-next-line security/detect-non-literal-fs-filename -- names come from readdirSync(migrations/)
  ...files.map((f) => `  { file: ${JSON.stringify(f)}, sql: ${JSON.stringify(readFileSync(join(dir, f), 'utf8'))} },`),
  '];',
  '',
].join('\n');

const prettierBin = join(root, 'node_modules', '.bin', 'prettier');
const formatted = existsSync(prettierBin)
  ? execFileSync(prettierBin, ['--stdin-filepath', out], { input: body, encoding: 'utf8' })
  : body;

if (process.argv.includes('--check')) {
  const current = existsSync(out) ? readFileSync(out, 'utf8') : '';
  if (current !== formatted) {
    console.error('migrations.generated.ts is out of date: run node scripts/db/embed-migrations.mjs');
    process.exit(1);
  }
  console.log(`migrations.generated.ts is up to date (${files.length} migrations)`);
} else {
  writeFileSync(out, formatted);
  console.log(`Wrote ${out} (${files.length} migrations)`);
}
